//! Private synthetic-only producer/refusal helper. Compile against exact a9e2429.
//! No CLI path or account overrides; no provider, credential or daemon methods.
use cirrove_core::{Change, ChangePage, Checkpoint, Cursor, Node, NodeKind, Scope};
use cirrove_service::journal::{JournalError, UploadIntent, UploadJournal, UploadState};
use cirrove_store::{Store, StoreError};
use rusqlite::{Connection, OpenFlags};
use serde_json::json;
use sha2::{Digest, Sha256};
use std::{
    fs::{File, OpenOptions},
    io::Write,
    os::unix::fs::OpenOptionsExt,
    path::{Path, PathBuf},
};

const ROOT: &str = "/home/dandiccf/Storage/cirrove-tmp/canary-compatibility-20261003-38106519-24f2-4299-bb47-35ebd99f3c98";
const ACCOUNT: &str = "synthetic-canary-compatibility";
const QUOTA: u64 = 1024 * 1024;
const PENDING: &[u8] = b"ordinary pending bytes from exact Canary producer\n";
const SEALED: &[u8] = b"sealed ordinary generation from exact Canary producer\n";
const DIRTY: &[u8] = b"dirty ordinary successor from exact Canary producer retained locally\n";

fn scope() -> Scope {
    Scope {
        account: ACCOUNT.into(),
        provider: "synthetic".into(),
        collection: "owned-fixture".into(),
    }
}
fn node(id: &str, name: &str, bytes: &[u8]) -> Node {
    Node {
        id: id.into(),
        parent_id: Some("root".into()),
        name: name.into(),
        kind: NodeKind::File,
        size: bytes.len() as u64,
        modified_unix: 1,
        etag: Some("synthetic-original-revision".into()),
        content_version: Some("synthetic-content-revision".into()),
        target: None,
        package: false,
    }
}
fn digest(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}
fn schema(path: &Path) -> Result<u32, Box<dyn std::error::Error>> {
    let db = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
    Ok(db.pragma_query_value(None, "user_version", |r| r.get(0))?)
}
fn paths() -> (PathBuf, PathBuf) {
    let root = PathBuf::from(ROOT);
    (root.join("journal"), root.join("metadata.db"))
}
fn produce() -> Result<(), Box<dyn std::error::Error>> {
    let root = Path::new(ROOT);
    // A failed attempt must never be replayed over an existing fixture.
    if root.exists() {
        return Err("fresh fixture root already exists".into());
    }
    cirrove_service::private_dir(root)?;
    let (journal_path, metadata_path) = paths();
    let mut journal = UploadJournal::open(&journal_path, ACCOUNT, QUOTA)?;
    let pending = journal.enqueue(
        scope(),
        UploadIntent::Create {
            parent: "root".into(),
            name: "pending.txt".into(),
        },
        PENDING,
    )?;
    let original = node("ordinary-working-item", "working.txt", b"");
    let working = journal.create_working(scope(), original.clone(), false, b"".as_slice())?;
    let (count, _) = journal.write_working(working.id, 0, SEALED)?;
    if count as usize != SEALED.len() {
        return Err("incomplete sealed write".into());
    }
    let sealed = journal
        .seal_working(working.id)?
        .ok_or("missing sealed generation")?;
    let (count, dirty) = journal.write_working(working.id, 0, DIRTY)?;
    if count as usize != DIRTY.len() || !dirty.dirty || dirty.latest != Some(sealed.id) {
        return Err("dirty successor contract failed".into());
    }
    File::open(journal_path.join("working").join(working.id.to_string()))?.sync_all()?;
    if journal.read_working(working.id, 0, 4096)? != DIRTY
        || journal.get(pending.id)?.state != UploadState::Pending
        || journal.get(sealed.id)?.state != UploadState::Pending
    {
        return Err("producer bytes/state failed".into());
    }
    drop(journal);
    let mut store = Store::open(&metadata_path)?;
    store.begin(&scope(), false)?;
    store.stage(
        &scope(),
        None,
        &ChangePage {
            changes: vec![Change::Upsert(original.clone())],
            checkpoint: Checkpoint::Complete(Cursor("synthetic-completed-checkpoint".into())),
        },
    )?;
    let cursor = store
        .begin(&scope(), false)?
        .ok_or("missing baseline cursor")?;
    let staged = node("staged-item", "staged.txt", b"staged metadata");
    store.stage(
        &scope(),
        Some(&cursor),
        &ChangePage {
            changes: vec![Change::Upsert(staged)],
            checkpoint: Checkpoint::Continue(Cursor("synthetic-interrupted-continuation".into())),
        },
    )?;
    if store.nodes(&scope())? != vec![original] {
        return Err("staged refresh replaced visible baseline".into());
    }
    drop(store);
    if schema(&journal_path.join("uploads.db"))? != 14 || schema(&metadata_path)? != 7 {
        return Err("producer was not exact Canary schema14/7".into());
    }
    let manifest = json!({"version":1,"source_commit":"a9e24291230b213c00843f939ee94c57213b1fa5",
        "root":ROOT,"account":ACCOUNT,"scope":scope(),"journal_schema":14,"metadata_schema":7,
        "pending":{"operation":pending.id,"size":PENDING.len(),"sha256":digest(PENDING)},
        "sealed":{"operation":sealed.id,"working":working.id,"size":SEALED.len(),"sha256":digest(SEALED)},
        "dirty":{"working":working.id,"generation":dirty.generation,"latest":dirty.latest,"size":DIRTY.len(),"sha256":digest(DIRTY)},
        "metadata":{"visible_ids":["ordinary-working-item"],"staged_ids":["staged-item"],
            "completed_cursor_sha256":digest(b"synthetic-completed-checkpoint"),
            "pending_cursor_sha256":digest(b"synthetic-interrupted-continuation")},
        "cloud_requests":0,"credential_access":false,"auto_seal_after_dirty_write":false});
    let mut output = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(root.join("producer.json"))?;
    serde_json::to_writer_pretty(&mut output, &manifest)?;
    output.write_all(b"\n")?;
    output.sync_all()?;
    File::open(root)?.sync_all()?;
    println!(
        "{{\"phase\":\"produce\",\"journal_schema\":14,\"metadata_schema\":7,\"pending_uploads\":2,\"dirty_working\":1,\"cloud_requests\":0}}"
    );
    Ok(())
}
fn refuse() -> Result<(), Box<dyn std::error::Error>> {
    let (journal_path, metadata_path) = paths();
    if schema(&journal_path.join("uploads.db"))? != 19 || schema(&metadata_path)? != 8 {
        return Err("refusal requires actual migrated current fixture".into());
    }
    if !matches!(
        UploadJournal::open(&journal_path, ACCOUNT, QUOTA),
        Err(JournalError::Schema)
    ) {
        return Err("exact Canary journal writer did not refuse newer state".into());
    }
    if !matches!(Store::open(&metadata_path), Err(StoreError::SchemaVersion)) {
        return Err("exact Canary metadata writer did not refuse newer state".into());
    }
    if schema(&journal_path.join("uploads.db"))? != 19 || schema(&metadata_path)? != 8 {
        return Err("old writer lowered schema after refusal".into());
    }
    println!(
        "{{\"phase\":\"refuse\",\"journal_refused\":true,\"metadata_refused\":true,\"cloud_requests\":0}}"
    );
    Ok(())
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let result = match args.as_slice() {
        [_, mode] if mode == "produce" => produce(),
        [_, mode] if mode == "refuse" => refuse(),
        _ => Err("exactly one finite phase required".into()),
    };
    if result.is_err() {
        eprintln!("synthetic Canary compatibility phase failed");
        std::process::exit(1);
    }
}

