//! Private finite-phase offline verifier, compiled against the current source.
use cirrove_core::{CancellationToken, ChangePage, Checkpoint, Cursor, Node, NodeKind, Scope};
use cirrove_service::journal::{
    RecoveryJournal, UploadIntent, UploadJournal, UploadRecord, UploadState,
};
use cirrove_store::Store;
use rusqlite::{Connection, OpenFlags, params};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::{
    fs::{File, OpenOptions},
    io::{Read, Write},
    os::unix::fs::OpenOptionsExt,
    path::{Path, PathBuf},
};
use uuid::Uuid;
const ROOT: &str = "/home/dandiccf/Storage/cirrove-tmp/canary-compatibility-20261003-38106519-24f2-4299-bb47-35ebd99f3c98";
const ACCOUNT: &str = "synthetic-canary-compatibility";
const PENDING: &[u8] = b"ordinary pending bytes from exact Canary producer\n";
const SEALED: &[u8] = b"sealed ordinary generation from exact Canary producer\n";
const DIRTY: &[u8] = b"dirty ordinary successor from exact Canary producer retained locally\n";
type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
fn digest(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}
fn scope() -> Scope {
    Scope {
        account: ACCOUNT.into(),
        provider: "synthetic".into(),
        collection: "owned-fixture".into(),
    }
}
fn original() -> Node {
    Node {
        id: "ordinary-working-item".into(),
        parent_id: Some("root".into()),
        name: "working.txt".into(),
        kind: NodeKind::File,
        size: 0,
        modified_unix: 1,
        etag: Some("synthetic-original-revision".into()),
        content_version: Some("synthetic-content-revision".into()),
        target: None,
        package: false,
    }
}
fn paths() -> (PathBuf, PathBuf) {
    (
        Path::new(ROOT).join("journal"),
        Path::new(ROOT).join("metadata.db"),
    )
}
fn ro(path: &Path) -> Result<Connection> {
    Ok(Connection::open_with_flags(
        path,
        OpenFlags::SQLITE_OPEN_READ_ONLY,
    )?)
}
fn schema(path: &Path) -> Result<u32> {
    Ok(ro(path)?.pragma_query_value(None, "user_version", |r| r.get(0))?)
}
fn id(manifest: &Value, section: &str, field: &str) -> Result<Uuid> {
    Ok(Uuid::parse_str(
        manifest[section][field]
            .as_str()
            .ok_or("missing producer identity")?,
    )?)
}
fn manifest(expected: &str) -> Result<Value> {
    let bytes = std::fs::read(Path::new(ROOT).join("producer.json"))?;
    if digest(&bytes) != expected {
        return Err("producer manifest digest changed".into());
    }
    let value: Value = serde_json::from_slice(&bytes)?;
    if value["version"] != 1
        || value["source_commit"] != "a9e24291230b213c00843f939ee94c57213b1fa5"
        || value["root"] != ROOT
        || value["account"] != ACCOUNT
        || value["scope"] != serde_json::to_value(scope())?
        || value["journal_schema"] != 14
        || value["metadata_schema"] != 7
    {
        return Err("producer scope/schema mismatch".into());
    }
    for (section, bytes) in [("pending", PENDING), ("sealed", SEALED), ("dirty", DIRTY)] {
        if value[section]["size"] != bytes.len() || value[section]["sha256"] != digest(bytes) {
            return Err("producer byte contract mismatch".into());
        }
    }
    if id(&value, "pending", "operation")? == id(&value, "sealed", "operation")?
        || id(&value, "sealed", "working")? != id(&value, "dirty", "working")?
        || value["dirty"]["latest"] != value["sealed"]["operation"]
    {
        return Err("producer operation chain mismatch".into());
    }
    Ok(value)
}
fn validate_rows(rows: &[UploadRecord], m: &Value) -> Result<()> {
    if rows.len() != 2 {
        return Err("unexpected upload inventory".into());
    }
    for (section, bytes) in [("pending", PENDING), ("sealed", SEALED)] {
        let operation = id(m, section, "operation")?;
        let row = rows
            .iter()
            .find(|r| r.id == operation)
            .ok_or("missing exact producer operation")?;
        let intent = if section == "pending" {
            UploadIntent::Create {
                parent: "root".into(),
                name: "pending.txt".into(),
            }
        } else {
            UploadIntent::Replace {
                item: "ordinary-working-item".into(),
                expected_etag: "synthetic-original-revision".into(),
            }
        };
        if row.scope != scope()
            || row.intent != intent
            || row.state != UploadState::Pending
            || row.size != bytes.len() as u64
            || row.sha256 != digest(bytes)
            || row.attempt.is_some()
            || row.remote.is_some()
            || !row.representation.is_file_bytes()
            || row.package_completion.is_some()
            || row.session_key.is_some()
            || row.transferred_bytes != 0
            || row.base.is_some()
            || row.working_file
                != if section == "sealed" {
                    Some(id(m, "sealed", "working")?)
                } else {
                    None
                }
        {
            return Err("ordinary pending record changed".into());
        }
    }
    Ok(())
}
fn metadata_snapshot() -> Result<Value> {
    let (_, path) = paths();
    let db = ro(&path)?;
    let key = serde_json::to_string(&scope())?;
    let feed: (Option<String>, bool, Option<String>, bool) = db.query_row(
        "SELECT cursor,pending,next_cursor,reset FROM feeds WHERE scope=?1",
        [&key],
        |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
    )?;
    if feed.0.as_deref() != Some("synthetic-completed-checkpoint")
        || !feed.1
        || feed.2.as_deref() != Some("synthetic-interrupted-continuation")
        || feed.3
    {
        return Err("completed cursor or staged continuation changed".into());
    }
    let nodes: Vec<(String, String)> = db
        .prepare("SELECT id,body FROM nodes WHERE scope=?1 ORDER BY id")?
        .query_map([&key], |r| Ok((r.get(0)?, r.get(1)?)))?
        .collect::<std::result::Result<_, _>>()?;
    if nodes.len() != 1
        || nodes[0].0 != "ordinary-working-item"
        || serde_json::from_str::<Node>(&nodes[0].1)? != original()
    {
        return Err("visible metadata changed before completed refresh".into());
    }
    let staged: Vec<(String, Option<String>)> = db
        .prepare("SELECT id,body FROM staged WHERE scope=?1 ORDER BY id")?
        .query_map([&key], |r| Ok((r.get(0)?, r.get(1)?)))?
        .collect::<std::result::Result<_, _>>()?;
    if staged.len() != 1 || staged[0].0 != "staged-item" {
        return Err("interrupted staged metadata lost".into());
    }
    let mut expected = original();
    expected.id = "staged-item".into();
    expected.name = "staged.txt".into();
    expected.size = 15;
    if serde_json::from_str::<Node>(staged[0].1.as_deref().ok_or("missing staged body")?)?
        != expected
    {
        return Err("staged metadata changed".into());
    }
    Ok(
        json!({"visible_sha256":digest(&serde_json::to_vec(&nodes)?),"staged_sha256":digest(&serde_json::to_vec(&staged)?),"feed_sha256":digest(&serde_json::to_vec(&feed)?)}),
    )
}
fn write_receipt(name: &str, value: &Value) -> Result<()> {
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(Path::new(ROOT).join(name))?;
    serde_json::to_writer_pretty(&mut file, value)?;
    file.write_all(b"\n")?;
    file.sync_all()?;
    File::open(ROOT)?.sync_all()?;
    Ok(())
}
fn recover(phase: &str, m: &Value) -> Result<()> {
    let expected = if phase == "recover14" {
        (14, 7)
    } else {
        (19, 8)
    };
    let (journal, metadata) = paths();
    let db = journal.join("uploads.db");
    if schema(&db)? != expected.0 || schema(&metadata)? != expected.1 {
        return Err("unexpected recovery schema".into());
    }
    let before = [
        digest(&std::fs::read(&db)?),
        digest(&std::fs::read(&metadata)?),
    ];
    let metadata_before = metadata_snapshot()?;
    let exports = Path::new(ROOT).join(phase);
    if exports.exists() {
        return Err("recovery phase already attempted".into());
    }
    cirrove_service::private_dir(&exports)?;
    let cancel = CancellationToken::new();
    let recovery = RecoveryJournal::open(&journal, ACCOUNT)?;
    validate_rows(&recovery.list(0, 100)?, m)?;
    let mut receipts = Vec::new();
    for (section, bytes) in [("pending", PENDING), ("sealed", SEALED)] {
        let operation = id(m, section, "operation")?;
        let destination = exports.join(format!("{section}.bin"));
        let receipt =
            recovery
                .local_export_source(operation)?
                .copy_to(&destination, &cancel, |_| {})?;
        if receipt.operation != operation
            || receipt.size != bytes.len() as u64
            || receipt.sha256 != digest(bytes)
            || std::fs::read(destination)? != bytes
        {
            return Err("sealed export identity/bytes mismatch".into());
        }
        receipts.push(serde_json::to_value(receipt)?);
    }
    let (working, next) = recovery.working_list(None, 100)?;
    if next.is_some()
        || working.len() != 1
        || working[0].file != id(m, "dirty", "working")?
        || working[0].generation
            != m["dirty"]["generation"]
                .as_u64()
                .ok_or("missing generation")?
        || working[0].size != DIRTY.len() as u64
        || working[0].recorded_size != DIRTY.len() as u64
        || working[0].unlinked
        || working[0].name != "working.txt"
    {
        return Err("dirty generation inventory changed".into());
    }
    let destination = exports.join("dirty.bin");
    let receipt = recovery.export_working(
        working[0].file,
        working[0].generation,
        &destination,
        &cancel,
        |_| {},
    )?;
    if receipt.sha256 != digest(DIRTY) || std::fs::read(destination)? != DIRTY {
        return Err("dirty bytes recovery mismatch".into());
    }
    receipts.push(serde_json::to_value(receipt)?);
    drop(recovery);
    if before
        != [
            digest(&std::fs::read(&db)?),
            digest(&std::fs::read(&metadata)?),
        ]
        || metadata_before != metadata_snapshot()?
        || schema(&db)? != expected.0
        || schema(&metadata)? != expected.1
    {
        return Err("read-only recovery modified state".into());
    }
    write_receipt(
        &format!("{phase}.json"),
        &json!({"phase":phase,"journal_schema":expected.0,"metadata_schema":expected.1,"db_sha256":before,"metadata":metadata_before,"receipts":receipts,"cloud_requests":0}),
    )?;
    println!(
        "{{\"phase\":\"{phase}\",\"exports_verified\":3,\"state_unchanged\":true,\"cloud_requests\":0}}"
    );
    Ok(())
}
fn migrate(m: &Value) -> Result<()> {
    let root = Path::new(ROOT);
    let before: Value = serde_json::from_slice(&std::fs::read(root.join("recover14.json"))?)?;
    let (journal, metadata) = paths();
    if schema(&journal.join("uploads.db"))? != 14
        || schema(&metadata)? != 7
        || root.join("migrate.json").exists()
    {
        return Err("migration requires unreplayed old fixture".into());
    }
    if before["metadata"] != metadata_snapshot()?
        || before["db_sha256"]
            != json!([
                digest(&std::fs::read(journal.join("uploads.db"))?),
                digest(&std::fs::read(&metadata)?)
            ])
    {
        return Err("old state changed since read-only recovery".into());
    }
    let writer = UploadJournal::open(&journal, ACCOUNT, 1024 * 1024)?;
    validate_rows(&writer.list(0, 100)?, m)?;
    for (section, bytes) in [("pending", PENDING), ("sealed", SEALED)] {
        let mut file = writer.payload(id(m, section, "operation")?)?;
        let mut actual = Vec::new();
        file.read_to_end(&mut actual)?;
        if actual != bytes {
            return Err("migration changed sealed bytes".into());
        }
    }
    let working = writer.working_files()?;
    if working.len() != 1
        || working[0].id != id(m, "dirty", "working")?
        || !working[0].dirty
        || working[0].latest != Some(id(m, "sealed", "operation")?)
        || working[0].generation
            != m["dirty"]["generation"]
                .as_u64()
                .ok_or("missing generation")?
        || working[0].scope != scope()
        || writer.read_working(working[0].id, 0, 4096)? != DIRTY
    {
        return Err("migration changed dirty successor".into());
    }
    drop(writer);
    let mut store = Store::open(&metadata)?;
    if store.nodes(&scope())? != vec![original()]
        || store.cursor(&scope())? != Some(Cursor("synthetic-completed-checkpoint".into()))
        || store.begin(&scope(), false)?
            != Some(Cursor("synthetic-interrupted-continuation".into()))
    {
        return Err("metadata migration lost visibility or continuation".into());
    }
    drop(store);
    if schema(&journal.join("uploads.db"))? != 19
        || schema(&metadata)? != 8
        || metadata_snapshot()? != before["metadata"]
    {
        return Err("actual forward migration did not preserve state".into());
    }
    write_receipt(
        "migrate.json",
        &json!({"phase":"migrate","journal_schema":19,"metadata_schema":8,"metadata":metadata_snapshot()?,"cloud_requests":0,"pending_uploads":2,"dirty_working":1}),
    )?;
    println!(
        "{}",
        r#"{"phase":"migrate","journal_schema":19,"metadata_schema":8,"cloud_requests":0}"#
    );
    Ok(())
}
fn resume() -> Result<()> {
    let root = Path::new(ROOT);
    if !root.join("recover19.json").is_file() || root.join("resume.json").exists() {
        return Err("resume requires recovered post-refusal fixture".into());
    }
    metadata_snapshot()?;
    let (_, metadata) = paths();
    let mut store = Store::open(metadata)?;
    let continuation = store
        .begin(&scope(), false)?
        .ok_or("missing interrupted continuation")?;
    if continuation != Cursor("synthetic-interrupted-continuation".into()) {
        return Err("unexpected continuation".into());
    }
    store.stage(
        &scope(),
        Some(&continuation),
        &ChangePage {
            changes: vec![],
            checkpoint: Checkpoint::Complete(Cursor("synthetic-next-completed-checkpoint".into())),
        },
    )?;
    let mut nodes = store.nodes(&scope())?;
    nodes.sort_by(|a, b| a.id.cmp(&b.id));
    let mut staged = original();
    staged.id = "staged-item".into();
    staged.name = "staged.txt".into();
    staged.size = 15;
    if nodes != vec![original(), staged]
        || store.cursor(&scope())? != Some(Cursor("synthetic-next-completed-checkpoint".into()))
    {
        return Err("completed refresh did not publish retained staged page".into());
    }
    drop(store);
    let db = ro(&Path::new(ROOT).join("metadata.db"))?;
    let key = serde_json::to_string(&scope())?;
    let count: i64 = db.query_row("SELECT COUNT(*) FROM staged WHERE scope=?1", [&key], |r| {
        r.get(0)
    })?;
    let (pending, next): (bool, Option<String>) = db.query_row(
        "SELECT pending,next_cursor FROM feeds WHERE scope=?1",
        params![key],
        |r| Ok((r.get(0)?, r.get(1)?)),
    )?;
    if count != 0 || pending || next.is_some() {
        return Err("completed refresh left incomplete staging".into());
    }
    drop(db);
    write_receipt(
        "resume.json",
        &json!({"phase":"resume","visible_nodes":2,"staged_remaining":0,"completed_cursor_sha256":digest(b"synthetic-next-completed-checkpoint"),"cloud_requests":0}),
    )?;
    println!(
        "{}",
        r#"{"phase":"resume","visible_nodes":2,"staged_remaining":0,"cloud_requests":0}"#
    );
    Ok(())
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let result = (|| -> Result<()> {
        if args.len() != 3 {
            return Err("phase and pinned producer manifest digest required".into());
        }
        let m = manifest(&args[2])?;
        match args[1].as_str() {
            "recover14" => recover("recover14", &m),
            "migrate" => migrate(&m),
            "recover19" => recover("recover19", &m),
            "resume" => resume(),
            _ => Err("unknown finite phase".into()),
        }
    })();
    if result.is_err() {
        eprintln!("synthetic current compatibility phase failed");
        std::process::exit(1);
    }
}

