import pathlib,os,subprocess,hashlib,json,sqlite3,sys,datetime
root=pathlib.Path('/home/dandiccf/Storage/cirrove-tmp/canary-compatibility-20261003-38106519-24f2-4299-bb47-35ebd99f3c98')
base=pathlib.Path(__file__).resolve().parent
phase=sys.argv[1]
assert phase in ['guard-fresh','old','before-refusal','after-refusal','after-pin-refusal','final']
for parent in [root,*root.parents]:
 assert not parent.is_symlink(), 'symlink ancestry'
assert root.parent.resolve()==root.parent
assert subprocess.check_output(['findmnt','-n','-o','FSTYPE','-T',str(root.parent)],text=True).strip()=='ext4'
mounts=json.loads(subprocess.check_output(['findmnt','--json','-o','TARGET'],text=True))
def flatten(items):
 for item in items:
  yield pathlib.Path(item['target'])
  yield from flatten(item.get('children',[]))
for mount in flatten(mounts['filesystems']):
 assert mount!=root and root not in mount.parents,'mount in fixture'
for protected in [pathlib.Path.home()/'Cloud/Cirrove-OneDrive',pathlib.Path.home()/'.local/state/cirrove',pathlib.Path.home()/'.local/bin/cirroved',pathlib.Path.cwd()/'.local-state']:
 protected=protected.resolve()
 assert protected!=root and protected not in root.parents and root not in protected.parents,'protected overlap'
result={'phase':phase,'root':str(root),'filesystem':'ext4','no_symlink_or_mount_in_fixture':True,'script_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest(),'at':datetime.datetime.now(datetime.timezone.utc).isoformat()}
if phase=='guard-fresh':
 assert not root.exists(),'fixture not fresh'
else:
 files={}
 for path in sorted(root.rglob('*')):
  assert not path.is_symlink(),'fixture symlink'
  if path.is_file():
   files[str(path.relative_to(root))]={'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'size':path.stat().st_size,'mode':path.stat().st_mode & 0o777}
 result['files']=files
 result['logical']={}
 for relative in ['journal/uploads.db','metadata.db']:
  path=root/relative
  assert not path.with_name(path.name+'-wal').exists() or path.with_name(path.name+'-wal').stat().st_size==0,'nonempty WAL; no immutable snapshot'
  db=sqlite3.connect(path.as_uri()+'?mode=ro&immutable=1',uri=True)
  assert db.execute('pragma integrity_check').fetchall()==[('ok',)]
  tables=[row[0] for row in db.execute("select name from sqlite_master where type='table' order by name")]
  def normalized(value):
   return {'bytes_sha256':hashlib.sha256(value).hexdigest(),'size':len(value)} if isinstance(value,bytes) else value
  digest_tables={}
  for table in tables:
   quoted='"'+table.replace('"','""')+'"'
   rows=sorted(json.dumps([normalized(v) for v in row],sort_keys=True,separators=(',',':')) for row in db.execute('select * from '+quoted))
   digest_tables[table]={'rows':len(rows),'sha256':hashlib.sha256(json.dumps(rows,separators=(',',':')).encode()).hexdigest()}
  result['logical'][relative]={'schema':db.execute('pragma user_version').fetchone()[0],'integrity':'ok','tables':digest_tables}
  db.close()
output=base/(phase+'-snapshot.json')
with output.open('x') as f: json.dump(result,f,indent=2);f.write('\n')
if phase in ['after-refusal','after-pin-refusal']:
 before=json.loads((base/('before-refusal-snapshot.json' if phase=='after-refusal' else 'old-snapshot.json')).read_text())
 assert before['logical']==result['logical'],'logical state changed'
 assert before['files']==result['files'],'files or sidecars changed; retained evidence requires investigation'
print(json.dumps({'phase':phase,'guard_passed':True,'snapshot':str(output),'file_count':len(result.get('files',{})),'refusal_unchanged':phase=='after-refusal'}))
